// Mimics @testing-library/jest-dom's vitest entry: it does `import { expect } from 'vitest';
// expect.extend(matchers)` as a TOP-LEVEL side-effect. Under the reuse path this is a KEPT
// node_module, so this side-effect runs ONCE (first file) and is never re-run for later files.
// The matchers therefore live only in the __customMatchers registry that this one `expect`
// reads — every later test file's `import { expect } from 'vitest'` must resolve to the SAME
// `expect` (reading the SAME registry) or the matcher is missing.
import { expect } from 'vitest';

const matchers = {
  toBeCustom(received) {
    const pass = received === 'custom';
    return {
      pass,
      message: () => `expected ${received} ${pass ? 'not ' : ''}to be the custom value`,
    };
  },
  toBeInTheDocumentish(received) {
    const pass = received != null;
    return {
      pass,
      message: () => `expected ${received} ${pass ? 'not ' : ''}to be in the document`,
    };
  },
};

expect.extend(matchers);
